[
  {
    "id": "c001",
    "name": "Preamble",
    "text": "THIS LOAN AND SECURITY AGREEMENT (this “Apreement”), is entered into as of July 17, 2007, by and between WELLS FARGO FOOTHILL, LLC, a Delaware limited liability company (“Lender”), and R.E, LOANS, LLC, a California limited liability company (“Fund”) and B-4 PARTNERS LLC, a California limited liability company (“Managers Fund and Manager each being referred to mdividually as a “Borrower”and individually and collectively, jointly and severally, as “Borrowers’’). The partics agree as follows:"
  },
  {
    "id": "c002",
    "name": "1.1 Definitions — “Account”",
    "text": "1.1 Definitions. As used in this Agreement, the following terms shall have the following definitions: “Account” means an account (as that term is defined in the Code)."
  },
  {
    "id": "c003",
    "name": "1.1 “Account Debtor”",
    "text": "“Account Debtor” means any Person who is obligated under, with respect to, or on account of, an Account, chattel paper, or a General Intangible, or is a debtor or obligor under, or a maker of, a Note Receryable,"
  },
  {
    "id": "c004",
    "name": "1.1 “ACH Transactions”",
    "text": "“ACH Transactions” means any cash management or related services {including the Automated Clearing House processing of electronic funds transfers through the direct Federal Reserve Fedline system) provided by a Bank Product Provider for the account of a Borrower or its Subsidiaries."
  },
  {
    "id": "c005",
    "name": "1.1 “Additional Documents”",
    "text": "“Additional Documents” has the meaning set forth in Section 4.4(c)."
  },
  {
    "id": "c006",
    "name": "1.1 “Advance” and “Advances”",
    "text": "“Advance” and “Advances” have the meanings set forth in Section 2.1{a)}."
  },
  {
    "id": "c007",
    "name": "1.1 “Adminisirative Borrower”",
    "text": "“Adminisirative Borrower” has the meaning specified therefor in Section 16.11."
  },
  {
    "id": "c008",
    "name": "1.1 “Affiliate”",
    "text": "“Affiliate” means, as applied fo any Person, any other Person who, directly or indirectly through one or more intermediaries, controls, is controlled by, or is under common contro! with, such Person. For purposes of this definition, “control” means the possession, dircetly or mdirectly through one or more intermediaries, of the power to direct the management and policies of a Person, whether througt the ownership of Steck, by contract, ar otherwise; provided, however, that, for purposes of the definition of Eligible Notes Receivable and Section 7.13 hereof: (a) any Person which owns directly or indirectly 10% or more of the Stock having ordinary voting power for the election of directors or other members of the governing body of a Person or 10% or more of the partnership, membership or other ownership interests of a Person (other than as a limited partner of such Person) shal! be deemed an Affiliate of such Persom, (b) each director (or comparable manager) of a Person shall be deemed to be an Affiliate of such Person, and (c) each partnership or joint venture in which a Person is a partner or joint venturer shall be deemed an Affiliate of such Person."
  },
  {
    "id": "c009",
    "name": "1.1 “Agreement”",
    "text": "“Agreement” has the meaning set forth in the preamble hereto,"
  },
  {
    "id": "c010",
    "name": "1.1 “Applicable Margin”",
    "text": "“Applicable Margin” means {a} one-half of one percent (0.50%) with respect to any portion of the Advances that isa Base Rate Loan, and (b)} two percent (2.00%) with respect to amy portion of the Advances that is a LIBOR Rate Loan."
  },
  {
    "id": "c011",
    "name": "1.1 “Applicable Prepayment Premium”",
    "text": "“Applicable Prepayment Premium” means, as of any date of determinahon, an amount equal to: (a) during the period from and after the Closing Date to the date that is the first anniversary of the Closing Date, one percent (1.00%) multiplied by the Maximum Revolver Amount in effect on such date; and (b) on and after the first anniversary of the Closing Date, zero percent (0.00%) multiplied by the Maximum Revolver Amount in effect on such date,"
  },
  {
    "id": "c012",
    "name": "1.1 “Anproved Debt”",
    "text": "“Anproved Debt” means the obligations of the Fund incurred pursuant to a Permitted Reorganization in connection with the distribution of Investor Membership Interests to a withdrawing member or the issuance of Subordinated Notes by the Fund in exchange for Investor Membership Interests as part of a Permitted reorganization, together with any obligations undertaken or assumed relating thereto,"
  },
  {
    "id": "c013",
    "name": "1.1 “Approved Title Insurance Company”",
    "text": "“Approved Title Insurance Company” means any of the title insurance companies listed on Schedule 5.21 attached hereto and such other fille insurance vornpanies as requesied by the Administrative Borrower and approved by Lender in writing from time to time, which approval will not be unreasonably withheld, but only to the extent such Approved Title Insurance Company has an office or an agent in the state or commonwealth where the Note Receivable Collateral which is to secure a Nate Receivable is located; provided, however, that Lender has the right, in its reasonable discretion, to remove any Approved Title Insurance Company from the list of Approved Title Insurance Companies, m a writing delivered to the Administrative Borrower."
  },
  {
    "id": "c014",
    "name": "1.1 “Assignec”",
    "text": "“Assignec” has the moaning sct forth in Section 14.1{a)."
  },
  {
    "id": "c015",
    "name": "1.1 “Authorized Appraisal”",
    "text": "“Authorized Appraisal” means an appraisal of real property (a) prepared by an appraiser meeting the qualifications set forth in Borrower's Required Procedures and acceptable to Lender, based on an appraisal that meets the minimum standards set forth in the regulalions set forth in 12 C_FLR. §323, as though the Fund were an stitution rcguiated by the Federal] Deposit Insurance Corporation (1e. a FIRREA-compliant appraisal), (b) prepared by an appraiser and in a manner otherwise acceptable to Lender, or (c}to the extent consistent with Borrower’s Required Procedures, an informal or unwritten estimate of value Dy Servicer,"
  },
  {
    "id": "c016",
    "name": "1.1 “Authorized Person”",
    "text": "“Authorized Person” means Barney Ng, Walter Nz, Keily Ng, Bruce Horvitz, or Stephanie Ne Kelly, or such other Person serying at such time as the Chief Financial Officer of Manager."
  },
  {
    "id": "c017",
    "name": "1.1 “Availability”",
    "text": "“Availability” means, as of any date of determination, the amount that Borrowers are entitlad to borrow as Advances hereunder (after giving effect to all then outstanding Obligations (other than Bank Product Obligations) and all sublimits and reserves then applicable hereunder)."
  },
  {
    "id": "c018",
    "name": "1.1 “Bank Product”",
    "text": "“Bank Product” means any financial accommodation extended to any Borrower or its Subsidiaries by a Bank Product Provider (other than pursuant to this Agreement) including: (a) credit cards, (b) credit card processing services, {c) debit cards, (d} purchase cards, {e) ACH Transactions, (f) cash management, including controlled dishursement, accounts or services, or (g} transactions under Hedge Agreements."
  },
  {
    "id": "c019",
    "name": "1.1 “Bank Product Agreements”",
    "text": "“Bank Product Agreements” means those agreements entered into from time to time by any Borrower or its Subsidiaries with a Bank Product Provider in connection with the obtaming vf any of the Bank Products."
  },
  {
    "id": "c020",
    "name": "1.1 “Bank Product Obligations”",
    "text": "“Bank Product Obligations” means all obligations, liabilities, contingent reimbursement obligations, fees, and expenses owing by any Borrower or its Subsidiaries to any Bank Product Provider pursuant to or evidenced by the Bank Product Agreements and irrespective of whether for the payment of money, whether direct or indirect, absolute or contingent, due or to become due, mow existing or hereatter arising, and including all such amounts that any Borrower or its Subsidiaries are obligated to reimburse to Lender as a result of Lender purchasing participations from, or executing indemnities or reimbursement obligations to, a Bank Product Provider with respect to the Bank Products provided by such Bank Product Provider to any Borrower or its Subsidiaries."
  },
  {
    "id": "c021",
    "name": "1.1 “Bank Product Provider”",
    "text": "“Bank Product Provider” means Wells Fargo or any cf its Affiliates."
  },
  {
    "id": "c022",
    "name": "1.1 “Rank Product Reserve”",
    "text": "“Rank Product Reserve” means, as of any date of determination, the amount of reserves that Lender has established (based npon the Bank Product Providers” reasonable determmation of the credit exposure of any Borrower and its Subsidiaries in respect of Bank Products} in respect of Bank Products then provided or outstanding,"
  },
  {
    "id": "c023",
    "name": "1.1 “Bankruptcy Code”",
    "text": "“Bankruptcy Code” means title 11 of the United States Code, as in effect from time to tne."
  },
  {
    "id": "c024",
    "name": "1.1 “Base LIBOR Rate”",
    "text": "“Base LIBOR Rate” means the rate per annum, determined by Lender in accordance with its customary procedures, and utilizing such electronic or other quotation sources as it considers appropriate (rounded upwards, if necessary, to the next 1/16%), ta be the rate at which Dollar deposits {for delivery on the first day of an Interest Period} tn the amount of $1,000,000 are offered to major banks in the London interbank market on or about 1:00 p.m. (Dallas time) twa (2) Business Days prior to the commencement of such Interest Period, for a term comparable to such Interest Period, which determination shall be conciusive in the absence of manifest error,"
  },
  {
    "id": "c025",
    "name": "1.1 “Base Rate”",
    "text": "“Base Rate” means the rate of interest announced, from time to time, within Wells Faren at its principal office in San Francisco as its “prime tate,” with the understanding that the “prime rate” Is one of Wells Fargo’s base rates (not necessarily the lowest of such rates) and serves as the basis upon which effective rates af inierest are calculated for those loans making reference thereto and is evidenced by the recording thereof after its announcement m such internal publications as Wells Fargo may designate."
  },
  {
    "id": "c026",
    "name": "1.1 “Base Rate Loan”",
    "text": "“Base Rate Loan” means each portion of an Advance that bears interest at a rate determined by reference to the Base Rate."
  },
  {
    "id": "c027",
    "name": "1.1 “Base Rate Notice”",
    "text": "“Base Rate Notice” means a written notice in the form of Exhibit B-1,"
  },
  {
    "id": "c028",
    "name": "1.1 “Benefit Plan”",
    "text": "“Benefit Plan” means a “defined benefit plan” (as defined in Section 3(35) of ERISA) for which Borrower or any Subsidiary cr ERISA Affiliate of Borrower has been an “employer” (as defined in Section 3(3) of ERISA} within the past stx years."
  },
  {
    "id": "c029",
    "name": "1.1 “Board of Directors”",
    "text": "“Board of Directors” means the board of directors (or comparable managers or managing members) of a Person or any committee thereof duly authorized to act on behalf of the board of directors (or comparable managers or managing members)."
  },
  {
    "id": "c030",
    "name": "1.1 “Books”",
    "text": "“Books” means all of each Borrower’s and its Subsidiaries’ now owned or hereafter acquired books and records (including all of their Records indicating, summarizing, or evidencing their assets (including the Collateral) or liabilities, all of each Borrower’s and its Subsidiaries’ Records relating LOAN AND SECURITY AGREEMENT fe) SANFDS73 2104.7 355171-11 of 93 ; to their business operations or financial condition, and ali of their goods or General Intangibles related to such information)."

  "text": "“Books” means all of each Borrower’s and its Subsidiaries’ now owned or hereafter acquired books and records (including all of their Records indicating, summarizing, or evidencing their assets (including the Collateral) or liabilities, all of each Borrower’s and its Subsidiaries’ Records relating LOAN AND SECURITY AGREEMENT fe) SANFDS73 2104.7 355171-11 of 93 ; to their business operations or financial condition, and ali of their goods or General Intangibles related to such information)."
},
{
  "id": "c031",
  "name": "1.1 “Borrower” and “Borrowers”",
  "text": "“Borrower” and “Borrowers” have the respective meanings set forth in the preamble ta this Agreement, and any reference in this Agreement to a Borrower shail be a reference ta each of and either of Fund and Manager,"
},
{
  "id": "c032",
  "name": "1.1 “Borrower Collateral”",
  "text": "“Borrower Collateral” means all of each Borrower’s now owned or hereafter acquired right, title, and interest in and to all property, including, without limitation, each of the following: (a) all of its Accounts, (b) all of its Books, (<) all of rts commercial tort clatns, (d} all of its Deposit Accounts, including any Escrow Accounts, (e] all of its Equipment, (ft all of its General Intangibles, (g) all of ts Inventory, th} all of its Investment Property (including all of its securities and Securities Accounts), (i) all of its Negotiable Collateral, including all of tts Notes Receivable, {j) all of its Supporting Obligations, {k} money or other assets of such Borrower that now or hereafter come into the possession, custody, ar contrel of the Lender, and (I) the proceeds amd products, whether tangible or intangible, of any of the foregoing, including proceeds of insurance covering any or all of the foregoing, and any and all Accounts, Books, Deposit Accounts, Equipment, General Intangibles, Inventory, Investrnaent Property, Negotiable Collateral, Real Property, Supporting Obligations, money, or other tangible or intangible property resulting from the sale, exchange, collection, or other disposition of any of the foregamg, or any portion thereof or interest therein, and the proceeds thereof."
},
{
  "id": "c033",
  "name": "1.1 “Borrower’s Required Procedures”",
  "text": "“Borrower’s Required Procedures” means the written policies, procedures and guidelmes of Fund as implemented by Manager or Servicer, specifically including underwriting, valuation (loan-tovalue) and documentation guidelines, standard documentation, and appraising, renewal, extension, modification, non-accrual and charge-off policies, in the form delivered to Lender and approved by Lender prior to the Closing Date, as amended from time te time with the por written approval of Lender, which approval shall be given er withheld in Lender’s sole discretion."
},
{
  "id": "c034",
  "name": "1.1 “Borrowing”",
  "text": "“Borrowing” means a borrowing hereunder consisting of Advances."
},
{
  "id": "c035",
  "name": "1.1 “Borrowing Base”",
  "text": "“Borrowing Base” means, as of arry date of determination, the result of: Loan AND SECURITY AGREEMENT 4 SANELI7EDIAF 358171-11 of 93 {a} twenty percent (20%) of the Net Eligible Notes Receivable, minus {b} the sum of (i} the Bank Product Reserve, and (ii) the aggregate amount of reserves, if any, established by Lender under Section 2.1(b)."
},
{
  "id": "c036",
  "name": "1.1 “Rooowing Base Certificate”",
  "text": "“Rooowing Base Certificate” means a certificate in the form of Exhibit B-2, used to determine the Borrowing Base from time to time, which certificate includes a list of alj Notes Receivable that are Eligible Notes Receivable and all Real Estate Owned as of the date thereof."
},
{
  "id": "c037",
  "name": "1.1 “Business Day”",
  "text": "“Business Day” means any day that is not a Saturday, Sunday, or other day on which banks are authorized or required to close in the State of New Yark or the State of California."
},
{
  "id": "c038",
  "name": "1.1 “Capitalized T.case Obligation”",
  "text": "“Capitalized T.case Obligation” means that portion of the obligations under a Capital Lease that is required to be capitalized in accordance with GAAP."
},
{
  "id": "c039",
  "name": "1.1 “Capital Lease”",
  "text": "“Capital Lease” means a lease that is required to be capitalized for financial reporting purposes m accordance with GAAP."
},
{
  "id": "c040",
  "name": "1.1 “Cash Equivalents”",
  "text": "“Cash Equivalents” means (a) marketable direct obligations issued by, or unconditionally guaranteed by, the United States or issued by any agency thereof and hacked by the full faith and credit of the United States, in each case maturing within 1 year from the date of acquisition thereof, (b} marketable direct obligations issued by any state of the United States or any political subdivision of any such state or any public instrumentality thereof maturing within | year from the date of acquisition thereof and, at the time of acquisilion, having one of the two highest ratings obtainable from either Standard & Poor’s Rating Group (“S&P”) or Moody’s Investors Service, Inc. (“Moody's”), (c) commercial paper maturimg no more than 270 days from the date of creation thereaf and, at the time of acquisition, having a rating of at least A-1 from S&P or at least P-1 from Moody's, (d} certificates of deposit or bankers’ acceptances maturing within | year from the date of acquisition thereof issued by any bank organized under the laws of the United States or any state thereof having at the date of acquisition thereof combined capital and surplus of not less than $250,000,000, (e¢} demand Deposit Accounts maintained with Gi) any bank that satisfies the criteria described in clause {d} above, or {j)} any other bank organized under the laws of the United States or any state thereof so Jong as the amount maintained with any such other bank is less than or equal to $100,000 and is insured by the Federal Deposit Insurance Corporation, and (f) Investments in money market funds or mutual funds substantially all of whose assets are invested in the lypes of asscts deseribed in clauses (a) through (e) above."
},
{
  "id": "c041",
  "name": "1.1 “Cash Management Account”",
  "text": "“Cash Management Account” has the meaning set forth in Section 2.6."
},
{
  "id": "c042",
  "name": "1.1 “Cash Management Agreements”",
  "text": "“Cash Management Agreements” means those certain cash management agreements, in form and substance satisfactory to Lender, each of which is among a Borrower or one of its Subsidiaries, Lender, and one of the Cash Management Banks."
},
{
  "id": "c043",
  "name": "1.1 “Cash Management Bank”",
  "text": "“Cash Management Bank” has the meaning set forth in Section 2.6."
},
{
  "id": "c044",
  "name": "1.1 “Change of Control”",
  "text": "“Change of Control’ means that (a) Manager ceases to be the sole manager or a managing member of Fund, (b) Permitted Holders fail to own and control, directly or indirectly, 100% of the Stock of Manager, (c) Permitted Holders fail to own and contral, directly or indirectly, 100% of the Stock of Servicer, or (d) either Fund or Manager ceases to own, directly or indirectly, and control 100% of the outstanding Steck of each of its Subsidiaries in existence as of the Closing Date."
},
{
  "id": "c045",
  "name": "1.1 “Closing Date”",
  "text": "“Closing Date” means the date of this Agreement."
},
{
  "id": "c046",
  "name": "1.1 “Closing Protection Letter”",
  "text": "“Closing Protection Letter” means a closing protection letter issued by an Approved Title Insurance Company with respect to a Settlement Agent."
},
{
  "id": "c047",
  "name": "1.1 “Code”",
  "text": "“Code” means the New York Uniform Commercial Code, as in effect from time to time; provided, however, that in the event that, by reason of mandatory provisions of law, any or all of the attachment, perfection, priority, or remedies with respect to Lender’s Lien on any Collateral is governed by the Uniform Commercial Code as enacted and in cffect in a jurisdiction other than the State of New York, the term “Code” shall mean the Unifonn Commercial Code as enacted and in effect in such other jurisdiction solely for purposes of the provisions thereof relating to such attachment, perfection, pricrity, or remedies."
},
{
  "id": "c048",
  "name": "1.1 “Collateral”",
  "text": "“Collateral” means the Borrower Collateral and all other assets and interests in assets and proceeds thereof now owned or hereafter acquired by any Borrower or ils Subsidiaries in or upon which a Lien is granted under any of the Loan Documents."
},
{
  "id": "c049",
  "name": "1.1 “Collateral Access Agreement”",
  "text": "“Collateral Access Agreement” means a landlord waiver, bailee letter, or acknowledgement agreement of any lessor, warchouseman, processor, consignee, ur other Person in possession of, having a Lien upon, or having rights or interests in any Collateral (excluding an Account Debtor), in each case, in form and substance satisfactory to Lender."
},
{
  "id": "c050",
  "name": "1.1 “Callections”",
  "text": "“Callections” means all cash, checks, notes, instruments, and other items of payment (including insurance proceeds, proceeds of cash sales, rental preceeds, and tax refunds),"
},
{
  "id": "c051",
  "name": "1.1 “Commercial Tort Claim Assignment”",
  "text": "“Commercial Tort Claim Assignment’ has the meaning set forth in Section 4.4(b)."
},
{
  "id": "c052",
  "name": "1.1 “Compliance Certificate”",
  "text": "“Compliance Certificate” means a certificate substantially in ihe form of Exhibit C-i delivered by the chief financial officer of Administrative Borrower to Lender."
},
{
  "id": "c053",
  "name": "1.1 “Control Agreement”",
  "text": "“Control Agreement” means a control agreement, in form and substance satisfactory to Lender, executed and delivered by a Borrower or one of its Subsidiaries, Lender, and the applicable securities intermediary (with respect to a Securities Account) or bank (with respect to a Depasit Account),"
},
{
  "id": "c054",
  "name": "1.1 “Daily Balance”",
  "text": "“Daily Balance” means, with respect to each day during the term of this Agreement, the amount of an Obligation owed at the end of such day."
},
{
  "id": "c055",
  "name": "1.1 “Default”",
  "text": "“Default”? meuns an event, condition, or default that, with the giving of notice, the passage of time, or both, would be an Event of Default."
},
{
  "id": "c056",
  "name": "1.1 “Defaulted Note Receivable”",
  "text": "“Defaulted Note Receivable” means any Note Receivable that Administrative Borrower or Lender deems to be non-performing or non-collectible, or with respect to which foreclosure proceedings have been initiated against any property securing such Note Receivable."
},
{
  "id": "c057",
  "name": "1.1 “Delinquent Note Receivable”",
  "text": "“Delinquent Note Receivable’ means any Note Receivable with respect to which any payment thereunder remains outstanding and ynpaid, im whole or in part, for more than ninety (90) days past the date it became due and payable according to the original face and tenor of such Note Receivable or as extended in accordance with Borrower’s Required Procedures."
},
{
  "id": "c058",
  "name": "1.1 “Deposit Account”",
  "text": "“Deposit Account” means any deposit accouni {as thai lerm is defined in the Code),"
},
{
  "id": "c059",
  "name": "1.1 “Desipnated Account”",
  "text": "“Desipnated Account” means the Deposit Account of Administrative Borrower identified on Schedule D-1."
},
{
  "id": "c060",
  "name": "1.1 “Designated Account Bank”",
  "text": "“Designated Account Bank” has the meaning ascribed thereto on Schedule D-1."
},
{
  "id": "c061",
  "name": "1.1 “Disbursement Letter”",
  "text": "“Disbursement Letter’ means an instructiona) Jetter executed and delivered by Administrative Borrower to Lender regarding the disbursements of the proceeds of an Advance on a Funding Date, the form and substance of which is satisfactory to Lender,"
},
{
  "id": "c062",
  "name": "1.1 “Dollars” or “$”",
  "text": "“Dollars” or “$\" means United States dollars,"
},
{
  "id": "c063",
  "name": "1.1 “Eligible Notes Keceivable”",
